INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(128741, 'ruRU', '', 'Порталы должны быть где-то здесь... Смотри в оба!', 24330),
(128742, 'ruRU', '', 'Можешь представить, как демоны проходят и получают лицом полную порцию лиан? Классика!', 24330),
(128743, 'ruRU', '', 'Это им покажет!', 24330),
(128744, 'ruRU', '', 'Через этот портал демоны ещё долго не пройдут!', 24330),
(128745, 'ruRU', '', 'Они... они пытаются развратить Голдрина! Быстрее, архидруид!', 24330),
(128757, 'ruRU', '', 'На прошлой неделе привезли тело моего кузена с Расколотого берега. Ожидаю, что за ним последует ещё немало.', 24330),
(128763, 'ruRU', '', 'Забавно, мне показалось, я только что услышал... Нет. Должно быть, воображение играет со мной шутки.', 24330),
(128782, 'ruRU', '', 'Не будь Андуином, будь Варианом! Он был куда крепче.', 24330),
(128835, 'ruRU', '', 'Вы слышали Голдрина! Нам нужно немедленно выяснить, кто руководит этими атаками! Нельзя терять время!', 24330),
(128854, 'ruRU', '', 'Я получила всё, что мне нужно было от этой твари, до твоего прихода. Я знаю, где их командир!', 24330),
(128858, 'ruRU', '', 'Идите, дети мои, и питайтесь!', 24330),
(128859, 'ruRU', '', 'Время кормления!', 24330),
(128867, 'ruRU', '', 'Этот командир попробует мой клинок!', 24330),
(128868, 'ruRU', '', 'Тебе не сопротивляться нам, Верховный хранитель. Разве ты не видишь? Это лучший путь. Единственный путь, которым мы можем победить их!', 24330),
(128869, 'ruRU', '', 'Ты всё ещё держишься за традиции? Твои заблудшие создатели больше не существуют. Прекрати это глупое сопротивление и образумься. Я не буду просить дважды.', 24330),
(128870, 'ruRU', '', 'Он сказал, что ты не станешь слушать. Тогда ты сгоришь, как и остальные!', 24330),
(128877, 'ruRU', '', 'Ты не... понимаешь...', 24330),
(128884, 'ruRU', '', 'Встретимся снова в Роще Снов, архидруид. Спасибо, что взял меня с собой!', 24330),
(128905, 'ruRU', '', 'Эй, придурок! Думаю, этот осколок, который ты мне принёс, сломан. Я даже пробовал бить его камнем!', 24330),
(128906, 'ruRU', '', 'Ох, привет. Ты кто?', 24330),
(128908, 'ruRU', '', 'Древний Осколок Связывания начинает излучать колоссальную силу.', 24330),
(128911, 'ruRU', '', 'Упс! Так вот что эта штука делает! Ну ладно.', 24330),
(128912, 'ruRU', '', 'Эй! Гляньте на все эти сокровища!', 24330),
(128982, 'ruRU', '', 'Пожалуйста, поспеши, Великий мастер. Выживание ордена зависит от твоего успеха!', 24330),
(129020, 'ruRU', '', 'Стражи с тобой, $ct.', 24330),
(129021, 'ruRU', '', 'Ещё порталы?! Да где, чёрт возьми, наше подкрепление?', 24330),
(129022, 'ruRU', '', 'Иллидан, как учтиво с твоей стороны наконец прибыть! Стражи, займитесь настоящей работой, пока охотники на демонов Иллидана резвятся со своими нетопырями.', 24330),
(129023, 'ruRU', '', 'Ты слишком скоро доверился Иллидану, Пророк. Я прослежу, чтобы он выполнил свой долг.', 24330),
(129044, 'ruRU', '', 'В самом деле? Как именно он удержит бесконечную армию демонов от вторжения и убийства всех подряд?', 24330),
(129045, 'ruRU', '', 'Это займёт всего момент!', 24330),
(129047, 'ruRU', '', 'Была не была. Держитесь!', 24330),
(129049, 'ruRU', '', 'Узрите нашу силу скверны!', 24330),
(129055, 'ruRU', '', 'Убийца всё ещё без сознания. Боюсь, что случится, если...', 24330),
(129056, 'ruRU', '', 'Это был жестокий удар по голове. И всё же наш Убийца крепкий, дорогая моя. Смотри!', 24330),
(129058, 'ruRU', '', 'Что за чёрт случилось с моими курами?', 24330),
(129083, 'ruRU', '', 'Прошу прощения, если я кажусь немного на нервах. Добро пожаловать в лавку.', 24330),
(129123, 'ruRU', '', '|TInterface\\Icons\\inv_misc_horn_03:20|t%s |cFFFF0000|Hspell:237937|h[Наделяет силой]|h|r $n!', 24330),
(129124, 'ruRU', '', '|TInterface\\Icons\\inv_misc_horn_03:20|t%s |cFFFF0000|Hspell:237937|h[Наделяет силой]|h|r себя и одного из союзников!', 24330),
(129125, 'ruRU', '', '|TInterface\\Icons\\inv_misc_horn_03:20|t%s |cFFFF0000|Hspell:237937|h[Наделяет силой]|h|r весь свой совет!', 24330),
(129141, 'ruRU', '', 'Сюда, $n! Какие-нибудь новости? Я не много слышал, но некоторые люди здесь ведут себя довольно странно.', 24330);
